// Key by the exact English question/option text so shuffling cannot mix up explanations.
// Evidence paragraph numbers are 1-based and refer to the lesson's adapted reading.
const g = (questionMeaning, choices, evidence, language) => ({
  questionMeaning,
  options: Object.fromEntries(choices.map(([text, meaning, reason]) => [text, { meaning, reason }])),
  evidence: evidence.map(([paragraph, quote, meaning]) => ({ paragraph, quote, meaning })),
  language: language.map(([term, meaning]) => ({ term, meaning }))
});

